#pragma GCC diagnostic pop
            break;
        case 1:
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wstrict-aliasing"
            if (_is.readMatch(reinterpret_cast<std::int16_t &>(_u.short_)) && _which != Which::short_) { _clear(); _which = Which::short_; }
#pragma GCC diagnostic pop
            break;
        case 2:
        case 4:
            if (_is.readMatch(_u.bits) && _which != static_cast<Which>(_id)) { _clear(); _which = static_cast<Which>(_id); }
            break;
        case 5:
            if (_is.readMatch(_u.num) && _which != Which::num) { _clear(); _which = Which::num; }
            break;
